/**
 * @file structs.ts
 * @brief Read and write engine structs through the generated wasm32 layouts.
 *
 * `STRUCTS` (raw.ts, generated by tools/gen_bindings.py) gives each struct's
 * size and field offsets; tools/host_shim/raw_check.cpp asserts them against
 * the real wasm32 ABI. These helpers turn a struct in the heap into a plain
 * object keyed by the C field names, and back:
 *
 * - `int`/`long` → number, `uint32_t` → number, `uint64_t` and
 *   `unsigned long long` → number,
 *   `float`/`double` → number, arrays → `number[]` (flattened row-major);
 * - `char[N]` and `const char*` → string (`""` for NULL);
 * - other pointers → number; a nested struct → object (arrays → object[]).
 *
 * @license  Apache-2.0
 */

import { checkedAlloc } from "./mem.js";
import { STRUCTS } from "./raw.js";
import type { OpenSwmmWasmModule } from "./types.js";

/** Name of a struct with a generated layout. */
export type StructName = keyof typeof STRUCTS;

/** A struct as a plain object keyed by C field name. */
export interface StructValue {
  [field: string]: StructField;
}
export type StructField = number | string | number[] | StructValue | StructValue[];

interface FieldLayout {
  offset: number;
  type: string;
  count?: number;
}
interface StructLayout {
  size: number;
  fields: Record<string, FieldLayout>;
}

const LAYOUTS = STRUCTS as unknown as Record<string, StructLayout>;

function layoutOf(name: string): StructLayout {
  const layout = LAYOUTS[name];
  if (!layout) throw new RangeError(`no generated layout for ${name}`);
  return layout;
}

/** `"const double[21]"` → `"double"`. */
function baseType(type: string): string {
  return type
    .replace(/\[\d+\]$/, "")
    .replace(/^const\s+/, "")
    .trim();
}

/** Byte size of one scalar of `base`. */
const SCALAR_SIZE: Record<string, number> = {
  int: 4,
  long: 4,
  uint32_t: 4,
  unsigned: 4,
  "unsigned int": 4,
  "unsigned long": 4,
  size_t: 4,
  uint64_t: 8,
  "unsigned long long": 8,
  float: 4,
  double: 8,
};

function readScalar(mod: OpenSwmmWasmModule, base: string, at: number): number {
  switch (base) {
    case "double":
      return mod.HEAPF64[at >> 3];
    case "float":
      return mod.HEAPF32[at >> 2];
    case "uint32_t":
    case "unsigned":
    case "unsigned int":
    case "unsigned long":
    case "size_t":
      return mod.HEAPU32[at >> 2];
    case "uint64_t":
    case "unsigned long long":
      return mod.HEAPU32[at >> 2] + mod.HEAPU32[(at >> 2) + 1] * 2 ** 32;
    default:
      return mod.HEAP32[at >> 2];
  }
}

function writeScalar(mod: OpenSwmmWasmModule, base: string, at: number, value: number): void {
  switch (base) {
    case "double":
      mod.HEAPF64[at >> 3] = value;
      break;
    case "float":
      mod.HEAPF32[at >> 2] = value;
      break;
    case "uint32_t":
    case "unsigned":
    case "unsigned int":
    case "unsigned long":
    case "size_t":
      mod.HEAPU32[at >> 2] = value;
      break;
    case "uint64_t":
    case "unsigned long long":
      mod.HEAPU32[at >> 2] = value % 2 ** 32;
      mod.HEAPU32[(at >> 2) + 1] = Math.floor(value / 2 ** 32);
      break;
    default:
      mod.HEAP32[at >> 2] = value;
  }
}

/** Read the struct `name` at `ptr`. */
export function readStruct(
  mod: OpenSwmmWasmModule,
  name: StructName | string,
  ptr: number,
): StructValue {
  const out: StructValue = {};
  for (const [field, f] of Object.entries(layoutOf(name).fields)) {
    const at = ptr + f.offset;
    const base = baseType(f.type);
    const count = f.count ?? 1;
    if (base === "char") {
      out[field] = mod.UTF8ToString(at, count);
    } else if (base.endsWith("*")) {
      const p = mod.HEAPU32[at >> 2];
      out[field] = /^(const\s+)?char\s*\*$/.test(base) ? (p ? mod.UTF8ToString(p) : "") : p;
    } else if (base in LAYOUTS) {
      const size = layoutOf(base).size;
      const items = Array.from({ length: count }, (_, i) => readStruct(mod, base, at + i * size));
      out[field] = f.count === undefined ? items[0] : items;
    } else {
      const size = SCALAR_SIZE[base] ?? 4;
      const values = Array.from({ length: count }, (_, i) => readScalar(mod, base, at + i * size));
      out[field] = f.count === undefined ? values[0] : values;
    }
  }
  return out;
}

/**
 * Write `values` into the struct `name` at `ptr`; fields left out keep their
 * bytes. Strings for `const char*` fields are copied to the heap and their
 * pointers pushed to `strings`, which the caller frees after the C call.
 */
export function writeStruct(
  mod: OpenSwmmWasmModule,
  name: StructName | string,
  ptr: number,
  values: StructValue,
  strings: number[],
): void {
  const fields = layoutOf(name).fields;
  for (const [field, value] of Object.entries(values)) {
    const f = fields[field];
    if (!f) throw new RangeError(`${name} has no field ${field}`);
    const at = ptr + f.offset;
    const base = baseType(f.type);
    const count = f.count ?? 1;
    if (base === "char") {
      mod.HEAPU8.fill(0, at, at + count);
      mod.stringToUTF8(String(value), at, count);
    } else if (base.endsWith("*")) {
      if (typeof value === "string") {
        const bytes = mod.lengthBytesUTF8(value) + 1;
        const p = checkedAlloc(mod, bytes);
        mod.stringToUTF8(value, p, bytes);
        strings.push(p);
        mod.HEAPU32[at >> 2] = p;
      } else {
        mod.HEAPU32[at >> 2] = Number(value);
      }
    } else if (base in LAYOUTS) {
      const size = layoutOf(base).size;
      const items = (Array.isArray(value) ? value : [value]) as StructValue[];
      items.forEach((item, i) => writeStruct(mod, base, at + i * size, item, strings));
    } else {
      const size = SCALAR_SIZE[base] ?? 4;
      const items = Array.isArray(value) ? (value as number[]) : [value as number];
      if (items.length > count) throw new RangeError(`${name}.${field} holds ${count} values`);
      items.forEach((v, i) => writeScalar(mod, base, at + i * size, Number(v)));
    }
  }
}

/**
 * Allocate `count` zeroed structs `name`, optionally fill them from `init`,
 * call `fn(ptr)` and free everything (strings included) afterwards.
 */
export function withStructs<T>(
  mod: OpenSwmmWasmModule,
  name: StructName | string,
  init: StructValue[],
  fn: (ptr: number) => T,
): T {
  const size = layoutOf(name).size;
  const ptr = checkedAlloc(mod, size * Math.max(init.length, 1));
  const strings: number[] = [];
  try {
    mod.HEAPU8.fill(0, ptr, ptr + size * Math.max(init.length, 1));
    init.forEach((values, i) => writeStruct(mod, name, ptr + i * size, values, strings));
    return fn(ptr);
  } finally {
    for (const p of strings) mod._free(p);
    mod._free(ptr);
  }
}

/** One zeroed (or `init`-filled) struct around `fn`. */
export function withStruct<T>(
  mod: OpenSwmmWasmModule,
  name: StructName | string,
  fn: (ptr: number) => T,
  init?: StructValue,
): T {
  return withStructs(mod, name, init ? [init] : [], fn);
}

/** `swe_m` → `sweM`, `ground_heat_wm2` → `groundHeatWm2`. */
const camelName = (field: string) =>
  field.replace(/_([a-z0-9])/gi, (_, c: string) => c.toUpperCase());

/** A struct `name` read by {@link readStruct}, with camelCase keys (nested structs too). */
export function camelStruct(name: StructName | string, row: StructValue): StructValue {
  const out: StructValue = {};
  for (const [field, f] of Object.entries(layoutOf(name).fields)) {
    if (!(field in row)) continue;
    const base = baseType(f.type);
    const value = row[field];
    out[camelName(field)] =
      base in LAYOUTS
        ? Array.isArray(value)
          ? (value as StructValue[]).map((v) => camelStruct(base, v))
          : camelStruct(base, value as StructValue)
        : value;
  }
  return out;
}

/**
 * camelCase values of struct `name` keyed by its C field names (nested
 * structs too), for {@link writeStruct}. The names come from the layout, so
 * they need not round-trip through a naming rule.
 * @throws RangeError for a key that is not a field of the struct.
 */
export function structFields(name: StructName | string, values: object): StructValue {
  const fields = layoutOf(name).fields;
  const byCamel = new Map(Object.keys(fields).map((field) => [camelName(field), field]));
  const out: StructValue = {};
  for (const [key, value] of Object.entries(values)) {
    const field = byCamel.get(key);
    if (!field) throw new RangeError(`${name} has no field ${key}`);
    const base = baseType(fields[field].type);
    out[field] =
      base in LAYOUTS
        ? Array.isArray(value)
          ? value.map((v: object) => structFields(base, v))
          : structFields(base, value as object)
        : (value as StructField);
  }
  return out;
}
